    is_entire_string_upper = name_str.isupper() and len(name_str.split()) > 1
    words = name_str.split(' ')
    title_words = []
    for idx, w in enumerate(words):
        w_lower = w.lower()
        if w_lower in minor_words:
            if idx == 0:
                title_words.append(w.capitalize())
            else:
                title_words.append(w_lower)
        elif len(w) == 2 and not any(v in w_lower for v in 'aeiouy'):
            # 2-letter non-vowel words like 'dj', 'mc', 'rs' are always acronyms
            title_words.append(w.upper())
        elif is_entire_string_upper:
            # Entire string was ALL CAPS: keep short acronyms without vowels, title-case regular words
            if len(w) <= 3 and not any(v in w_lower for v in 'aeiou'):
                title_words.append(w)
            elif len(w) <= 3 and w_lower in ['dva', 'u2']:
                title_words.append(w)
            else:
                title_words.append(w.capitalize())
        elif w.isupper() and 2 <= len(w) <= 5:
            # Preserves mixed-case acronyms like 'RS Tangent', 'Clock DVA', 'MDFMK'
            title_words.append(w)
        else:
            title_words.append(w.capitalize())
    return ' '.join(title_words)

